CREATE TABLE health_records (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, animal_id BIGINT UNSIGNED NOT NULL, financial_transaction_id BIGINT UNSIGNED NULL, recorded_by_user_id BIGINT UNSIGNED NULL, record_date DATE NOT NULL, record_type ENUM('vaccination','treatment','checkup','illness','death','other') NOT NULL, diagnosis VARCHAR(255) NULL, treatment VARCHAR(500) NULL, veterinarian_name VARCHAR(150) NULL, cost DECIMAL(15,2) NOT NULL DEFAULT 0.00, notes TEXT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_health_records_ft (financial_transaction_id), KEY idx_health_animal_date (animal_id,record_date), CONSTRAINT chk_health_cost CHECK (cost >= 0), CONSTRAINT fk_health_animal FOREIGN KEY (animal_id) REFERENCES animals(id) ON DELETE RESTRICT, CONSTRAINT fk_health_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT, CONSTRAINT fk_health_user FOREIGN KEY (recorded_by_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
